mapper.select:
select

from upload_task
where file_hash = #{fileHash}
  and file_size = #{fileSize}
  and status = 1
limit 1

mapper.update:
update upload_task
set uploaded_bytes = uploaded_bytes + #{delta}
where upload_id = #{uploadId}

update upload_task
set status       = #{status},
    storage_path = #{storagePath}
where upload_id = #{uploadId}

mapper.select:
select

from upload_task


        and status = #{status}


order by id desc
limit #{offset}, #{size}

select count(*)
from upload_task


        and status = #{status}
